import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        String filePath = "<tmp>";

        List<String[]> employees = new ArrayList<>();

        try (BufferedReader br = new BufferedReader(new FileReader(filePath))) {
            String line;
            boolean first = true;
            while ((line = br.readLine()) != null) {
                if (first) {
                    first = false;
                    continue;
                }
                if (line.trim().isEmpty()) continue;
                String[] parts = line.split(",");
                employees.add(parts);
            }
        }

        Map<String, List<Double>> deptSalaries = new TreeMap<>();
        Map<String, Integer> deptCount = new TreeMap<>();
        double totalBudget = 0;
        double maxSalary = -1;
        String maxName = "";

        for (String[] emp : employees) {
            String dept = emp[2].trim();
            double salary = Double.parseDouble(emp[3].trim());

            deptSalaries.computeIfAbsent(dept, k -> new ArrayList<>()).add(salary);
            deptCount.merge(dept, 1, Integer::sum);
            totalBudget += salary;

            if (salary > maxSalary) {
                maxSalary = salary;
                maxName = emp[1].trim();
            }
        }

        System.out.println("=== Salary Report ===");
        System.out.println();
        System.out.println("Average Salary by Department:");
        for (Map.Entry<String, List<Double>> entry : deptSalaries.entrySet()) {
            String dept = entry.getKey();
            List<Double> salaries = entry.getValue();
            double avg = salaries.stream().mapToDouble(Double::doubleValue).average().orElse(0);
            System.out.printf("  %s: $%,.2f%n", dept, avg);
        }

        System.out.println();
        System.out.printf("Highest Paid: %s ($%,.0f)%n", maxName, maxSalary);

        System.out.println();
        System.out.println("Departments with >2 employees:");
        for (Map.Entry<String, Integer> entry : deptCount.entrySet()) {
            if (entry.getValue() > 2) {
                System.out.printf("  %s (%d employees)%n", entry.getKey(), entry.getValue());
            }
        }

        System.out.println();
        System.out.printf("Total Budget: $%,.0f%n", totalBudget);
    }
}

