let sortedDepts = deptSalaries.keys.sorted()

let highestPaid = employees.max { $0.salary < $1.salary }!

var deptCounts: [String: Int] = [:]
for emp in employees {
    deptCounts[emp.department, default: 0] += 1
}
let deptsOver2 = deptCounts.filter { $0.value > 2 }.sorted { $0.key < $1.key }

let totalBudget = employees.reduce(0.0) { $0 + $1.salary }

func formatCurrency(_ value: Double, decimals: Int) -> String {
    let formatter = NumberFormatter()
    formatter.numberStyle = .decimal
    formatter.minimumFractionDigits = decimals
    formatter.maximumFractionDigits = decimals
    let formatted = formatter.string(from: NSNumber(value: value)) ?? "0"
    return "$" + formatted
}

print("=== Salary Report ===")
print("")
print("Average Salary by Department:")
for dept in sortedDepts {
    let salaries = deptSalaries[dept]!
    let avg = salaries.reduce(0, +) / Double(salaries.count)
    print("  \(dept): \(formatCurrency(avg, decimals: 2))")
