import * as fs from 'fs';

const logFile = '<tmp>';
const content = fs.readFileSync(logFile, 'utf-8');
const lines = content.split('\n').filter(line => line.trim() !== '');

const levelCounts: Map<string, number> = new Map();
const errorComponentCounts: Map<string, number> = new Map();
const errorMessages: Set<string> = new Set();
const hourCounts: Map<string, number> = new Map();

const regex = /^\[(\d{4}-\d{2}-\d{2} (\d{2}):\d{2}:\d{2})\] (\w+) \(([^)]+)\) - (.+)$/;

for (const line of lines) {
    const match = line.match(regex);
    if (!match) continue;

    const [, , hour, level, component, message] = match;

    levelCounts.set(level, (levelCounts.get(level) || 0) + 1);
    hourCounts.set(hour, (hourCounts.get(hour) || 0) + 1);

    if (level === 'ERROR') {
        errorComponentCounts.set(component, (errorComponentCounts.get(component) || 0) + 1);
        errorMessages.add(message);
    }
}

let output = '=== Log Analysis ===\n';
output += '\n';
output += 'Entries by Level:\n';
const sortedLevels = [...levelCounts.entries()].sort((a, b) => a[0].localeCompare(b[0]));
for (const [level, count] of sortedLevels) {
    output += `  ${level}: ${count}\n`;
}
output += '\n';

const sortedErrorComponents = [...errorComponentCounts.entries()].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
if (sortedErrorComponents.length > 0) {
    output += `Component with Most Errors: ${sortedErrorComponents[0][0]} (${sortedErrorComponents[0][1]} errors)\n`;
} else {
    output += `Component with Most Errors: N/A (0 errors)\n`;
}
output += '\n';

output += 'Unique Error Messages:\n';
const sortedMessages = [...errorMessages].sort((a, b) => a.localeCompare(b));
for (const msg of sortedMessages) {
    output += `  - ${msg}\n`;
}
output += '\n';

const sortedHours = [...hourCounts.entries()].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
if (sortedHours.length > 0) {
    output += `Busiest Hour: ${sortedHours[0][0]}:00 (${sortedHours[0][1]} entries)\n`;
} else {
    output += `Busiest Hour: N/A (0 entries)\n`;
}

process.stdout.write(output);

