import Foundation

let filePath = "<tmp>"

guard let content = try? String(contentsOfFile: filePath, encoding: .utf8) else {
    FileHandle.standardError.write("Error reading file\n".data(using: .utf8)!)
    exit(1)
}

let lines = content.components(separatedBy: "\n").filter { !$0.isEmpty }

var levelCounts: [String: Int] = [:]
var errorComponentCounts: [String: Int] = [:]
var errorMessages: Set<String> = []
var hourCounts: [String: Int] = [:]

let pattern = "^\\[(\\d{4}-\\d{2}-\\d{2} (\\d{2}):\\d{2}:\\d{2})\\] (\\w+) \\(([^)]+)\\) - (.+)$"
let regex = try! NSRegularExpression(pattern: pattern)

for line in lines {
    let range = NSRange(line.startIndex..<line.endIndex, in: line)
    guard let match = regex.firstMatch(in: line, options: [], range: range),
          match.numberOfRanges >= 6 else { continue }

    let hourStr = String(line[Range(match.range(at: 2), in: line)!])
    let level = String(line[Range(match.range(at: 3), in: line)!])
    let component = String(line[Range(match.range(at: 4), in: line)!])
    let message = String(line[Range(match.range(at: 5), in: line)!])

    levelCounts[level, default: 0] += 1
    hourCounts[hourStr, default: 0] += 1

    if level == "ERROR" {
        errorComponentCounts[component, default: 0] += 1
        errorMessages.insert(message)
    }
}

print("=== Log Analysis ===")
print("")
print("Entries by Level:")
for level in levelCounts.keys.sorted() {
    print("  \(level): \(levelCounts[level]!)")
}
print("")
if let topComponent = errorComponentCounts.max(by: { $0.value < $1.value }) {
    print("Component with Most Errors: \(topComponent.key) (\(topComponent.value) errors)")
} else {
    print("Component with Most Errors: N/A (0 errors)")
}
print("")
print("Unique Error Messages:")
for msg in errorMessages.sorted() {
    print("  - \(msg)")
}
print("")
if let topHour = hourCounts.max(by: { $0.value < $1.value }) {
    print("Busiest Hour: \(topHour.key):00 (\(topHour.value) entries)")
}

