use std::collections::BTreeMap;
use std::fs;

fn format_with_commas(int_part: &str) -> String {
    let chars: Vec<char> = int_part.chars().collect();
    let mut result = String::new();
    for (i, c) in chars.iter().enumerate() {
        if i > 0 && (chars.len() - i) % 3 == 0 {
            result.push(',');
        }
        result.push(*c);
    }
    result
}

fn main() {
    let path = "<tmp>";
    let content = fs::read_to_string(path).expect("Failed to read CSV file");

    let lines: Vec<&str> = content.lines().collect();

    let mut employees: Vec<(String, String, f64)> = Vec::new();

    for line in &lines[1..] {
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }
        let fields: Vec<&str> = trimmed.split(',').collect();
        if fields.len() < 4 {
            continue;
        }
        let name = fields[1].trim().to_string();
        let department = fields[2].trim().to_string();
        let salary: f64 = fields[3].trim().parse().expect("Failed to parse salary");
        employees.push((name, department, salary));
    }

    let mut dept_salaries: BTreeMap<String, (f64, usize)> = BTreeMap::new();
    for (_, dept, salary) in &employees {
        let entry = dept_salaries.entry(dept.clone()).or_insert((0.0, 0));
        entry.0 += salary;
        entry.1 += 1;
    }

    let highest = employees.iter().max_by(|a, b| a.2.partial_cmp(&b.2).unwrap());

    let total: f64 = employees.iter().map(|e| e.2).sum();

    println!("=== Salary Report ===");
    println!();
    println!("Average Salary by Department:");
    for (dept, (sum, count)) in &dept_salaries {
        let avg = sum / *count as f64;
        let avg_str = format!("{:.2}", avg);
        let parts: Vec<&str> = avg_str.split('.').collect();
        let int_part = format_with_commas(parts[0]);
        let dec_part = parts.get(1).copied().unwrap_or("00");
        println!("  {}: ${}.{}", dept, int_part, dec_part);
    }
    println!();
    if let Some((name, _, salary)) = highest {
        let salary_int = *salary as i64;
        let salary_str = format!("{}", salary_int);
        let comma_str = format_with_commas(&salary_str);
        println!("Highest Paid: {} (${})", name, comma_str);
    }
    println!();
    println!("Departments with >2 employees:");
    for (dept, (_, count)) in &dept_salaries {
        if *count > 2 {
            println!("  {} ({} employees)", dept, count);
        }
    }
    println!();
    let total_int = total as i64;
    let total_str = format!("{}", total_int);
    let total_comma = format_with_commas(&total_str);
    println!("Total Budget: ${}", total_comma);
}

