    w = edge["weight"]
    adj[u].append((v, w))
    adj[v].append((u, w))

INF = float('inf')
dist = {node: INF for node in nodes}
dist["A"] = 0

pq = [(0, "A")]
visited = set()

while pq:
    d, u = heapq.heappop(pq)
    if u in visited:
        continue
    visited.add(u)
    for v, w in adj[u]:
        if v not in visited:
            new_dist = d + w
            if new_dist < dist[v]:
                dist[v] = new_dist
                heapq.heappush(pq, (new_dist, v))

print("=== Shortest Paths from A ===")
print()
for node in sorted(nodes):
    d = dist[node]
    if d == INF:
        print(f"A -> {node}: unreachable")
