        // Format: [YYYY-MM-DD HH:MM:SS] LEVEL (component) - message
        let bracket_end = line.find(']').expect("No closing bracket found");
        let timestamp = &line[1..bracket_end]; // "YYYY-MM-DD HH:MM:SS"

        // Hour is at index 11..13 in "YYYY-MM-DD HH:MM:SS"
        let hour = &timestamp[11..13];
        *hour_counts.entry(hour.to_string()).or_insert(0) += 1;

        // After ']', trim leading space
        let after_bracket = line[bracket_end + 1..].trim_start();

        // Parse LEVEL (up to first space)
        let level_end = after_bracket.find(' ').expect("No space after level");
        let level = &after_bracket[..level_end];
        *level_counts.entry(level.to_string()).or_insert(0) += 1;

        // After level, expect " (component) - message"
        let after_level = &after_bracket[level_end + 1..];

        // Parse component inside parentheses
        let paren_start = after_level.find('(').expect("No opening paren");
        let paren_end = after_level.find(')').expect("No closing paren");
        let component = &after_level[paren_start + 1..paren_end];

        // After ')', expect " - message"
        let after_component = &after_level[paren_end + 1..];
        let message = after_component.trim_start();
        let message = if message.starts_with("- ") {
            &message[2..]
        } else {
            message
        };

        if level == "ERROR" {
            *error_component_counts.entry(component.to_string()).or_insert(0) += 1;
            error_messages.push(message.to_string());
        }
    }

    // Build output
    println!("=== Log Analysis ===");
    println!();

    println!("Entries by Level:");
    let mut levels: Vec<&String> = level_counts.keys().collect();
    levels.sort();
    for level in levels {
        println!("  {}: {}", level, level_counts[level]);
    }

    println!();

    // Component with Most Errors
    let mut components: Vec<(&String, &usize)> = error_component_counts.iter().collect();
    components.sort_by(|a, b| b.1.cmp(a.1).then(a.0.cmp(b.0)));
    if let Some((comp, count)) = components.first() {
        println!("Component with Most Errors: {} ({} errors)", comp, count);
    } else {
        println!("Component with Most Errors: N/A (0 errors)");
    }

    println!();

    println!("Unique Error Messages:");
    let mut unique_msgs: Vec<&String> = error_messages.iter().collect();
    unique_msgs.sort();
    unique_msgs.dedup();
    for msg in unique_msgs {
        println!("  - {}", msg);
    }

    println!();

    // Busiest Hour
    let mut hours: Vec<(&String, &usize)> = hour_counts.iter().collect();
    hours.sort_by(|a, b| b.1.cmp(a.1).then(a.0.cmp(b.0)));
    if let Some((h, c)) = hours.first() {
        println!("Busiest Hour: {}:00 ({} entries)", h, c);
    }
}
