        List<Map<String, String>> products = parseJsonArray(json);

        List<Map<String, String>> filtered = products.stream()
                .filter(p -> Double.parseDouble(p.get("price")) > 50.00)
                .sorted(Comparator.comparing(p -> p.get("name")))
                .collect(Collectors.toList());

        System.out.println("=== Filtered Products (price > $50.00) ===");
        System.out.println();
        double total = 0.0;
        for (Map<String, String> p : filtered) {
            double price = Double.parseDouble(p.get("price"));
            System.out.printf("%s: $%.2f%n", p.get("name"), price);
            total += price;
        }
        System.out.println();
        System.out.printf("Count: %d%n", filtered.size());
        System.out.printf("Total: $%.2f%n", total);
    }

    static List<Map<String, String>> parseJsonArray(String json) {
        List<Map<String, String>> result = new ArrayList<>();
        int start = json.indexOf('[');
        int end = json.lastIndexOf(']');
        if (start == -1 || end == -1 || end <= start) return result;

        String inner = json.substring(start + 1, end);
        int i = 0;
        while (i < inner.length()) {
            int objStart = inner.indexOf('{', i);
            if (objStart == -1) break;
            int objEnd = findMatchingBrace(inner, objStart);
            if (objEnd == -1) break;
            String objStr = inner.substring(objStart + 1, objEnd);
            result.add(parseObject(objStr));
            i = objEnd + 1;
        }
        return result;
    }

    static int findMatchingBrace(String s, int start) {
        int depth = 0;
        for (int i = start; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '{') depth++;
            else if (c == '}') {
                depth--;
                if (depth == 0) return i;
            } else if (c == '"') {
                i++;
                while (i < s.length() && s.charAt(i) != '"') {
                    if (s.charAt(i) == '\\') i++;
                    i++;
                }
            }
        }
        return -1;
    }

    static Map<String, String> parseObject(String s) {
        Map<String, String> map = new LinkedHashMap<>();
        int i = 0;
        while (i < s.length()) {
            while (i < s.length() && (Character.isWhitespace(s.charAt(i)) || s.charAt(i) == ',')) i++;
            if (i >= s.length()) break;
            if (s.charAt(i) != '"') break;

            int keyEnd = findStringEnd(s, i);
            String key = s.substring(i + 1, keyEnd);
            i = keyEnd + 1;

            while (i < s.length() && s.charAt(i) != ':') i++;
            i++;

            while (i < s.length() && Character.isWhitespace(s.charAt(i))) i++;

            String value;
            if (i < s.length() && s.charAt(i) == '"') {
                int valEnd = findStringEnd(s, i);
                value = s.substring(i + 1, valEnd);
                i = valEnd + 1;
            } else {
                int valStart = i;
                while (i < s.length() && s.charAt(i) != ',' && s.charAt(i) != '}' && !Character.isWhitespace(s.charAt(i))) {
                    i++;
                }
                value = s.substring(valStart, i).trim();
            }
            map.put(key, value);
        }
        return map;
    }

    static int findStringEnd(String s, int start) {
        int i = start + 1;
        while (i < s.length()) {
            if (s.charAt(i) == '\\') {
                i += 2;
            } else if (s.charAt(i) == '"') {
                return i;
            } else {
                i++;
            }
        }
        return s.length() - 1;
    }
}

