        for (String n : nodes) {
            adj.put(n, new ArrayList<>());
        }

        int edgesKey = json.indexOf("\"edges\"");
        int edgesStart = json.indexOf('[', edgesKey);
        int edgesEnd = findMatchingBracket(json, edgesStart);
        String edgesStr = json.substring(edgesStart + 1, edgesEnd);

        int i = 0;
