import java.io.*;
import java.util.*;

public class Main {
    static String json;
    static int pos;

    public static void main(String[] args) throws Exception {
        String a = readFile("<tmp>");
        String b = readFile("<tmp>");

        Object objA = parse(a);
        Object objB = parse(b);

        Object merged = merge(objA, objB);

        System.out.print(prettyPrint(merged, 0));
        System.out.println();
    }

    static String readFile(String path) throws Exception {
        StringBuilder sb = new StringBuilder();
        try (BufferedReader br = new BufferedReader(new FileReader(path))) {
            char[] buf = new char[4096];
            int n;
            while ((n = br.read(buf)) != -1) {
                sb.append(buf, 0, n);
            }
        }
        return sb.toString();
    }

    static Object parse(String s) {
        json = s;
        pos = 0;
        return parseValue();
    }

    static void skipWhitespace() {
        while (pos < json.length() && Character.isWhitespace(json.charAt(pos))) pos++;
    }

    static Object parseValue() {
        skipWhitespace();
        char c = json.charAt(pos);
        if (c == '{') return parseObject();
        if (c == '[') return parseArray();
        if (c == '"') return parseString();
        if (c == 't') { pos += 4; return Boolean.TRUE; }
        if (c == 'f') { pos += 5; return Boolean.FALSE; }
        if (c == 'n') { pos += 4; return null; }
        return parseNumber();
    }

    static Map<String, Object> parseObject() {
        Map<String, Object> map = new LinkedHashMap<>();
        pos++;
        skipWhitespace();
        if (json.charAt(pos) == '}') { pos++; return map; }
        while (true) {
            skipWhitespace();
            String key = parseString();
            skipWhitespace();
            pos++;
            Object value = parseValue();
            map.put(key, value);
            skipWhitespace();
            if (json.charAt(pos) == ',') { pos++; }
            else { pos++; break; }
        }
        return map;
    }

    static List<Object> parseArray() {
        List<Object> list = new ArrayList<>();
        pos++;
        skipWhitespace();
        if (json.charAt(pos) == ']') { pos++; return list; }
        while (true) {
            Object value = parseValue();
            list.add(value);
            skipWhitespace();
            if (json.charAt(pos) == ',') { pos++; }
            else { pos++; break; }
        }
        return list;
    }

    static String parseString() {
        pos++;
        StringBuilder sb = new StringBuilder();
        while (true) {
            char c = json.charAt(pos);
            if (c == '\\') {
                pos++;
                char esc = json.charAt(pos);
                switch (esc) {
                    case '"': sb.append('"'); break;
                    case '\\': sb.append('\\'); break;
                    case '/': sb.append('/'); break;
                    case 'b': sb.append('\b'); break;
                    case 'f': sb.append('\f'); break;
                    case 'n': sb.append('\n'); break;
                    case 'r': sb.append('\r'); break;
                    case 't': sb.append('\t'); break;
                    case 'u':
                        String hex = json.substring(pos + 1, pos + 5);
                        sb.append((char) Integer.parseInt(hex, 16));
                        pos += 4;
                        break;
                }
            } else if (c == '"') {
                pos++;
                break;
            } else {
                sb.append(c);
            }
            pos++;
        }
        return sb.toString();
    }

    static Object parseNumber() {
        int start = pos;
        boolean isDouble = false;
        while (pos < json.length()) {
            char c = json.charAt(pos);
            if (c == '.' || c == 'e' || c == 'E') isDouble = true;
            if (c == '-' || c == '+' || c == '.' || c == 'e' || c == 'E' || (c >= '0' && c <= '9')) pos++;
            else break;
