import java.io.*;
import java.nio.file.*;
import java.util.*;

public class Main {
    static class FileEntry {
        String relPath;
        int lines;
        long chars;
        FileEntry(String relPath, int lines, long chars) {
            this.relPath = relPath;
            this.lines = lines;
            this.chars = chars;
        }
    }

    public static void main(String[] args) throws Exception {
        Path root = Path.of("<tmp>");
        Map<String, List<FileEntry>> groups = new TreeMap<>();
        Set<Path> visited = new HashSet<>();

        walkDir(root, root, groups, visited);

        StringBuilder sb = new StringBuilder();
        sb.append("=== File Tree Analysis ===\n");
        sb.append("\n");

        int totalFiles = 0;
        long totalLines = 0;
        long totalChars = 0;

        for (Map.Entry<String, List<FileEntry>> entry : groups.entrySet()) {
            String ext = entry.getKey();
            List<FileEntry> files = entry.getValue();
            files.sort(Comparator.comparing(f -> f.relPath));

            long extLines = 0;
            long extChars = 0;
            for (FileEntry f : files) {
                extLines += f.lines;
                extChars += f.chars;
            }

            sb.append("Extension: ").append(ext).append("\n");
            sb.append("  Files: ").append(files.size()).append("\n");
            sb.append("  Total Lines: ").append(extLines).append("\n");
            sb.append("  Total Characters: ").append(extChars).append("\n");
            for (FileEntry f : files) {
                sb.append("    ").append(f.relPath).append(": ").append(f.lines).append(" lines, ").append(f.chars).append(" chars\n");
            }

            totalFiles += files.size();
            totalLines += extLines;
            totalChars += extChars;
        }

        sb.append("\n");
        sb.append("Total: ").append(totalFiles).append(" files, ").append(totalLines).append(" lines, ").append(totalChars).append(" characters\n");

        System.out.print(sb.toString());
    }

    static void walkDir(Path current, Path root, Map<String, List<FileEntry>> groups, Set<Path> visited) throws IOException {
        if (!visited.add(current)) return;

        try (DirectoryStream<Path> stream = Files.newDirectoryStream(current)) {
            for (Path entry : stream) {
                if (Files.isSymbolicLink(entry)) continue;
                if (Files.isDirectory(entry)) {
                    walkDir(entry, root, groups, visited);
                } else if (Files.isRegularFile(entry)) {
                    String fileName = entry.getFileName().toString();
                    String ext = "";
                    int dotIdx = fileName.lastIndexOf('.');
                    if (dotIdx > 0) {
                        ext = fileName.substring(dotIdx);
                    }

                    String relPath = root.relativize(entry).toString().replace('\\', '/');

                    int lines = countLines(entry);
                    long chars = Files.size(entry);

                    groups.computeIfAbsent(ext, k -> new ArrayList<>()).add(new FileEntry(relPath, lines, chars));
                }
            }
        }
    }

    static int countLines(Path path) throws IOException {
        int count = 0;
        try (BufferedReader reader = Files.newBufferedReader(path)) {
            while (reader.readLine() != null) {
                count++;
            }
        }
        return count;
    }
}

