use std::collections::BTreeMap;

#[derive(Debug, Clone)]
enum Json {
    Null,
    Bool(bool),
    Number(f64),
    String(String),
    Array(Vec<Json>),
    Object(BTreeMap<String, Json>),
}

fn json_eq(a: &Json, b: &Json) -> bool {
    match (a, b) {
        (Json::Null, Json::Null) => true,
        (Json::Bool(a), Json::Bool(b)) => a == b,
        (Json::Number(a), Json::Number(b)) => a == b,
        (Json::String(a), Json::String(b)) => a == b,
        (Json::Array(a), Json::Array(b)) => {
            a.len() == b.len() && a.iter().zip(b.iter()).all(|(x, y)| json_eq(x, y))
        }
        (Json::Object(a), Json::Object(b)) => {
            a.len() == b.len()
                && a.iter().all(|(k, v)| b.get(k).map_or(false, |bv| json_eq(v, bv)))
        }
        _ => false,
    }
}

struct Parser<'a> {
    data: &'a [u8],
    pos: usize,
}

impl<'a> Parser<'a> {
    fn new(data: &'a str) -> Self {
        Parser {
            data: data.as_bytes(),
            pos: 0,
        }
    }

    fn skip_whitespace(&mut self) {
        while self.pos < self.data.len() {
            match self.data[self.pos] {
                b' ' | b'\t' | b'\n' | b'\r' => self.pos += 1,
                _ => break,
            }
        }
    }

    fn parse(&mut self) -> Json {
        self.skip_whitespace();
        let json = self.parse_value();
        self.skip_whitespace();
        json
    }

    fn parse_value(&mut self) -> Json {
        self.skip_whitespace();
        if self.pos >= self.data.len() {
            panic!("Unexpected end of input");
        }
        match self.data[self.pos] {
            b'{' => self.parse_object(),
            b'[' => self.parse_array(),
            b'"' => Json::String(self.parse_string()),
            b't' => {
                self.expect("true");
                Json::Bool(true)
            }
            b'f' => {
                self.expect("false");
                Json::Bool(false)
            }
            b'n' => {
                self.expect("null");
                Json::Null
            }
            _ => self.parse_number(),
        }
    }

    fn expect(&mut self, s: &str) {
        for &b in s.as_bytes() {
            if self.pos >= self.data.len() || self.data[self.pos] != b {
                panic!("Parse error: expected '{}'", s);
            }
            self.pos += 1;
        }
    }

    fn parse_string(&mut self) -> String {
        self.pos += 1;
        let mut result = String::new();
        loop {
            if self.pos >= self.data.len() {
                panic!("Unterminated string");
            }
            let c = self.data[self.pos];
            if c == b'"' {
                self.pos += 1;
                break;
            } else if c == b'\\' {
                self.pos += 1;
                if self.pos >= self.data.len() {
                    panic!("Unterminated escape");
                }
                let esc = self.data[self.pos];
                match esc {
                    b'"' => result.push('"'),
                    b'\\' => result.push('\\'),
                    b'/' => result.push('/'),
                    b'b' => result.push('\u{0008}'),
                    b'f' => result.push('\u{000C}'),
                    b'n' => result.push('\n'),
                    b'r' => result.push('\r'),
                    b't' => result.push('\t'),
                    b'u' => {
                        self.pos += 1;
                        if self.pos + 4 > self.data.len() {
                            panic!("Invalid \\u escape");
                        }
                        let hex = std::str::from_utf8(&self.data[self.pos..self.pos + 4])
                            .unwrap();
                        let code = u32::from_str_radix(hex, 16).unwrap();
                        self.pos += 4;
                        if (0xD800..=0xDBFF).contains(&code) {
                            if self.pos + 1 < self.data.len()
                                && self.data[self.pos] == b'\\'
                                && self.data[self.pos + 1] == b'u'
                            {
                                self.pos += 2;
                                let hex2 =
                                    std::str::from_utf8(&self.data[self.pos..self.pos + 4])
                                        .unwrap();
                                let code2 = u32::from_str_radix(hex2, 16).unwrap();
                                self.pos += 4;
                                let combined =
                                    0x10000 + ((code - 0xD800) << 10) + (code2 - 0xDC00);
                                result.push(char::from_u32(combined).unwrap_or('\u{FFFD}'));
                            } else {
                                result.push(char::from_u32(code).unwrap_or('\u{FFFD}'));
                            }
                        } else {
                            result.push(char::from_u32(code).unwrap_or('\u{FFFD}'));
                        }
                    }
                    _ => panic!("Invalid escape character"),
                }
                self.pos += 1;
            } else if c < 0x80 {
                result.push(c as char);
                self.pos += 1;
            } else {
                let slice = std::str::from_utf8(&self.data[self.pos..]).unwrap();
                let ch = slice.chars().next().unwrap();
                result.push(ch);
                self.pos += ch.len_utf8();
            }
        }
        result
    }

    fn parse_number(&mut self) -> Json {
        let start = self.pos;
        if self.pos < self.data.len() && self.data[self.pos] == b'-' {
            self.pos += 1;
        }
        while self.pos < self.data.len() && self.data[self.pos].is_ascii_digit() {
            self.pos += 1;
        }
        if self.pos < self.data.len() && self.data[self.pos] == b'.' {
            self.pos += 1;
            while self.pos < self.data.len() && self.data[self.pos].is_ascii_digit() {
                self.pos += 1;
            }
        }
        if self.pos < self.data.len()
            && (self.data[self.pos] == b'e' || self.data[self.pos] == b'E')
        {
            self.pos += 1;
            if self.pos < self.data.len()
                && (self.data[self.pos] == b'+' || self.data[self.pos] == b'-')
            {
                self.pos += 1;
            }
            while self.pos < self.data.len() && self.data[self.pos].is_ascii_digit() {
                self.pos += 1;
            }
        }
        let s = std::str::from_utf8(&self.data[start..self.pos]).unwrap();
        let n: f64 = s.parse().unwrap();
        Json::Number(n)
    }

    fn parse_array(&mut self) -> Json {
        self.pos += 1;
        let mut items = Vec::new();
        self.skip_whitespace();
        if self.pos < self.data.len() && self.data[self.pos] == b']' {
            self.pos += 1;
            return Json::Array(items);
        }
        loop {
            let item = self.parse_value();
            items.push(item);
            self.skip_whitespace();
            if self.pos >= self.data.len() {
                panic!("Unterminated array");
            }
            match self.data[self.pos] {
                b',' => {
                    self.pos += 1;
                }
                b']' => {
                    self.pos += 1;
                    break;
                }
                _ => panic!("Expected ',' or ']' in array"),
            }
        }
        Json::Array(items)
    }

    fn parse_object(&mut self) -> Json {
        self.pos += 1;
        let mut map = BTreeMap::new();
        self.skip_whitespace();
        if self.pos < self.data.len() && self.data[self.pos] == b'}' {
            self.pos += 1;
            return Json::Object(map);
        }
        loop {
            self.skip_whitespace();
            if self.pos >= self.data.len() || self.data[self.pos] != b'"' {
                panic!("Expected string key in object");
            }
            let key = self.parse_string();
            self.skip_whitespace();
            if self.pos >= self.data.len() || self.data[self.pos] != b':' {
                panic!("Expected ':' in object");
            }
            self.pos += 1;
            let value = self.parse_value();
            map.insert(key, value);
            self.skip_whitespace();
            if self.pos >= self.data.len() {
                panic!("Unterminated object");
            }
            match self.data[self.pos] {
                b',' => {
                    self.pos += 1;
                }
                b'}' => {
                    self.pos += 1;
                    break;
                }
                _ => panic!("Expected ',' or '}}' in object"),
            }
        }
        Json::Object(map)
    }
}

fn deep_merge(a: Json, b: Json) -> Json {
    match (a, b) {
        (Json::Object(mut ma), Json::Object(mb)) => {
            for (k, v) in mb {
                match ma.remove(&k) {
                    Some(av) => {
                        ma.insert(k, deep_merge(av, v));
                    }
                    None => {
                        ma.insert(k, v);
                    }
                }
            }
            Json::Object(ma)
        }
        (Json::Array(mut arr_a), Json::Array(arr_b)) => {
            for item in arr_b {
                if !arr_a.iter().any(|x| json_eq(x, &item)) {
                    arr_a.push(item);
                }
            }
            Json::Array(arr_a)
        }
        (_, b) => b,
    }
}

fn escape_string(s: &str, out: &mut String) {
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '\u{0008}' => out.push_str("\\b"),
            '\u{000C}' => out.push_str("\\f"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
}

