static void skip_whitespace(Parser *p) {
    while (p->pos < p->len) {
        char c = p->data[p->pos];
        if (c == ' ' || c == '\t' || c == '\n' || c == '\r') p->pos++;
        else break;
    }
}

static char *parse_string(Parser *p) {
    if (p->data[p->pos] != '"') return NULL;
    p->pos++;
    int cap = 64;
    char *buf = (char *)malloc(cap);
    int len = 0;
    while (p->pos < p->len && p->data[p->pos] != '"') {
        char c = p->data[p->pos];
        if (c == '\\') {
            p->pos++;
            if (p->pos >= p->len) break;
            char esc = p->data[p->pos];
            switch (esc) {
                case '"': if (len+1>=cap){cap*=2;buf=realloc(buf,cap);} buf[len++]='"'; break;
                case '\\': if (len+1>=cap){cap*=2;buf=realloc(buf,cap);} buf[len++]='\\'; break;
                case '/': if (len+1>=cap){cap*=2;buf=realloc(buf,cap);} buf[len++]='/'; break;
                case 'b': if (len+1>=cap){cap*=2;buf=realloc(buf,cap);} buf[len++]='\b'; break;
                case 'f': if (len+1>=cap){cap*=2;buf=realloc(buf,cap);} buf[len++]='\f'; break;
                case 'n': if (len+1>=cap){cap*=2;buf=realloc(buf,cap);} buf[len++]='\n'; break;
                case 'r': if (len+1>=cap){cap*=2;buf=realloc(buf,cap);} buf[len++]='\r'; break;
                case 't': if (len+1>=cap){cap*=2;buf=realloc(buf,cap);} buf[len++]='\t'; break;
                case 'u': {
                    if (p->pos + 4 >= p->len) { p->pos++; break; }
                    char hex[5] = {0};
                    for (int i = 0; i < 4; i++) hex[i] = p->data[p->pos + 1 + i];
                    p->pos += 4;
                    unsigned int cp = (unsigned int)strtoul(hex, NULL, 16);
                    if (cp < 0x80) {
                        if (len+1>=cap){cap*=2;buf=realloc(buf,cap);}
                        buf[len++]=(char)cp;
                    } else if (cp < 0x800) {
                        if (len+2>=cap){cap*=2;buf=realloc(buf,cap);}
                        buf[len++]=(char)(0xC0|(cp>>6));
                        buf[len++]=(char)(0x80|(cp&0x3F));
                    } else {
                        if (len+3>=cap){cap*=2;buf=realloc(buf,cap);}
                        buf[len++]=(char)(0xE0|(cp>>12));
                        buf[len++]=(char)(0x80|((cp>>6)&0x3F));
                        buf[len++]=(char)(0x80|(cp&0x3F));
