static double parse_number(Parser *p) {
    int start = p->pos;
    if (p->pos < p->len && (p->data[p->pos]=='-' || p->data[p->pos]=='+')) p->pos++;
    while (p->pos < p->len && (isdigit((unsigned char)p->data[p->pos]) || p->data[p->pos]=='.' ||
