        p->pos++;
    }
    char *tmp = (char *)malloc(p->pos - start + 1);
    memcpy(tmp, p->data + start, p->pos - start);
    tmp[p->pos - start] = '\0';
    double val = strtod(tmp, NULL);
    free(tmp);
    return val;
}

static JSONValue *parse_value(Parser *p);

static JSONValue *parse_object(Parser *p) {
    JSONValue *obj = new_value(JSON_OBJECT);
    p->pos++; /* skip '{' */
    skip_whitespace(p);
    if (p->pos < p->len && p->data[p->pos] == '}') { p->pos++; return obj; }
    while (p->pos < p->len) {
        skip_whitespace(p);
        if (p->pos >= p->len) break;
        char *key = parse_string(p);
        if (!key) break;
        skip_whitespace(p);
        if (p->pos < p->len && p->data[p->pos] == ':') p->pos++;
