            obj->obj_keys = (char **)realloc(obj->obj_keys, obj->obj_cap * sizeof(char *));
            obj->obj_values = (JSONValue **)realloc(obj->obj_values, obj->obj_cap * sizeof(JSONValue *));
        }
        obj->obj_keys[obj->obj_count] = key;
        obj->obj_values[obj->obj_count] = val;
        obj->obj_count++;
        skip_whitespace(p);
        if (p->pos < p->len && p->data[p->pos] == ',') { p->pos++; }
        else if (p->pos < p->len && p->data[p->pos] == '}') { p->pos++; break; }
        else break;
    }
    return obj;
}

static JSONValue *parse_array(Parser *p) {
    JSONValue *arr = new_value(JSON_ARRAY);
    p->pos++; /* skip '[' */
    skip_whitespace(p);
    if (p->pos < p->len && p->data[p->pos] == ']') { p->pos++; return arr; }
    while (p->pos < p->len) {
        JSONValue *item = parse_value(p);
        if (arr->array_count >= arr->array_cap) {
            arr->array_cap = arr->array_cap == 0 ? 8 : arr->array_cap * 2;
            arr->array_items = (JSONValue **)realloc(arr->array_items, arr->array_cap * sizeof(JSONValue *));
        }
        arr->array_items[arr->array_count] = item;
        arr->array_count++;
        skip_whitespace(p);
        if (p->pos < p->len && p->data[p->pos] == ',') { p->pos++; }
        else if (p->pos < p->len && p->data[p->pos] == ']') { p->pos++; break; }
        else break;
    }
    return arr;
