static JSONValue *parse_value(Parser *p) {
    skip_whitespace(p);
    if (p->pos >= p->len) return NULL;
    char c = p->data[p->pos];
    if (c == '{') return parse_object(p);
    if (c == '[') return parse_array(p);
    if (c == '"') {
        JSONValue *v = new_value(JSON_STRING);
        v->string = parse_string(p);
        return v;
    }
    if (c == 't') { p->pos += 4; JSONValue *v = new_value(JSON_BOOL); v->boolean = 1; return v; }
    if (c == 'f') { p->pos += 5; JSONValue *v = new_value(JSON_BOOL); v->boolean = 0; return v; }
    if (c == 'n') { p->pos += 4; return new_value(JSON_NULL); }
    JSONValue *v = new_value(JSON_NUMBER);
    v->number = parse_number(p);
    return v;
}

static int json_equal(const JSONValue *a, const JSONValue *b) {
    if (a->type != b->type) return 0;
    switch (a->type) {
        case JSON_NULL: return 1;
        case JSON_BOOL: return a->boolean == b->boolean;
        case JSON_NUMBER: return a->number == b->number;
        case JSON_STRING: return a->string && b->string && strcmp(a->string, b->string) == 0;
        case JSON_ARRAY:
            if (a->array_count != b->array_count) return 0;
            for (int i = 0; i < a->array_count; i++) {
                if (!json_equal(a->array_items[i], b->array_items[i])) return 0;
            }
            return 1;
        case JSON_OBJECT:
            if (a->obj_count != b->obj_count) return 0;
            for (int i = 0; i < a->obj_count; i++) {
                int found = 0;
                for (int j = 0; j < b->obj_count; j++) {
                    if (strcmp(a->obj_keys[i], b->obj_keys[j]) == 0) {
                        if (!json_equal(a->obj_values[i], b->obj_values[j])) return 0;
                        found = 1;
                        break;
                    }
                }
                if (!found) return 0;
            }
            return 1;
    }
    return 0;
}

