            if (!find_obj_value(a, b->obj_keys[i])) {
                add_obj_pair(result, b->obj_keys[i], deep_copy(b->obj_values[i]));
            }
        }
        return result;
    }
    if (a->type == JSON_ARRAY && b->type == JSON_ARRAY) {
        JSONValue *result = new_value(JSON_ARRAY);
        for (int i = 0; i < a->array_count; i++) {
            add_arr_item(result, deep_copy(a->array_items[i]));
        }
        for (int i = 0; i < b->array_count; i++) {
            if (!array_contains(result, b->array_items[i])) {
                add_arr_item(result, deep_copy(b->array_items[i]));
            }
        }
        return result;
    }
    /* Scalar conflict or type mismatch: B overrides A */
    return deep_copy(b);
}

static int key_compare(const void *a, const void *b) {
    const char *ka = *(const char *const *)a;
    const char *kb = *(const char *const *)b;
    return strcmp(ka, kb);
}

static void sort_obj_keys(JSONValue *obj) {
    if (obj->obj_count <= 1) return;
    /* Sort indices */
    int *idx = (int *)malloc(obj->obj_count * sizeof(int));
    for (int i = 0; i < obj->obj_count; i++) idx[i] = i;
    /* Simple insertion sort on indices by key */
    for (int i = 1; i < obj->obj_count; i++) {
        int key = idx[i];
        int j = i - 1;
        while (j >= 0 && strcmp(obj->obj_keys[idx[j]], obj->obj_keys[key]) > 0) {
            idx[j+1] = idx[j];
            j--;
        }
        idx[j+1] = key;
    }
    char **new_keys = (char **)malloc(obj->obj_count * sizeof(char *));
    JSONValue **new_vals = (JSONValue **)malloc(obj->obj_count * sizeof(JSONValue *));
    for (int i = 0; i < obj->obj_count; i++) {
        new_keys[i] = obj->obj_keys[idx[i]];
        new_vals[i] = obj->obj_values[idx[i]];
    }
    free(obj->obj_keys);
    free(obj->obj_values);
    obj->obj_keys = new_keys;
    obj->obj_values = new_vals;
    /* Recursively sort children */
    for (int i = 0; i < obj->obj_count; i++) {
        if (obj->obj_values[i]->type == JSON_OBJECT) sort_obj_keys(obj->obj_values[i]);
        if (obj->obj_values[i]->type == JSON_ARRAY) {
            for (int j = 0; j < obj->obj_values[i]->array_count; j++) {
                if (obj->obj_values[i]->array_items[j]->type == JSON_OBJECT)
                    sort_obj_keys(obj->obj_values[i]->array_items[j]);
            }
        }
    }
}

static void sort_array_objects(JSONValue *arr) {
    for (int i = 0; i < arr->array_count; i++) {
        if (arr->array_items[i]->type == JSON_OBJECT) sort_obj_keys(arr->array_items[i]);
        if (arr->array_items[i]->type == JSON_ARRAY) sort_array_objects(arr->array_items[i]);
    }
}

static void sort_all(JSONValue *v) {
    if (v->type == JSON_OBJECT) sort_obj_keys(v);
    else if (v->type == JSON_ARRAY) sort_array_objects(v);
}

static void print_string_escaped(const char *s) {
    fputc('"', stdout);
    for (const char *p = s; *p; p++) {
        unsigned char c = (unsigned char)*p;
        switch (c) {
            case '"': fputs("\\\"", stdout); break;
            case '\\': fputs("\\\\", stdout); break;
            case '\b': fputs("\\b", stdout); break;
            case '\f': fputs("\\f", stdout); break;
            case '\n': fputs("\\n", stdout); break;
            case '\r': fputs("\\r", stdout); break;
            case '\t': fputs("\\t", stdout); break;
            default:
                if (c < 0x20) {
                    fprintf(stdout, "\\u%04x", c);
                } else {
                    fputc(c, stdout);
                }
                break;
        }
    }
    fputc('"', stdout);
}

static void print_number(double d) {
    if (d == (double)(long long)d && fabs(d) < 1e15) {
        fprintf(stdout, "%lld", (long long)d);
    } else {
        char buf[64];
        snprintf(buf, sizeof(buf), "%.17g", d);
        /* Try to clean up trailing zeros for cleaner output */
        fprintf(stdout, "%s", buf);
    }
}

static void print_json(const JSONValue *v, int indent) {
    switch (v->type) {
        case JSON_NULL:
            fputs("null", stdout);
            break;
        case JSON_BOOL:
            fputs(v->boolean ? "true" : "false", stdout);
            break;
        case JSON_NUMBER:
            print_number(v->number);
            break;
        case JSON_STRING:
            print_string_escaped(v->string);
            break;
        case JSON_ARRAY:
            if (v->array_count == 0) {
                fputs("[]", stdout);
                break;
            }
            fputs("[\n", stdout);
            for (int i = 0; i < v->array_count; i++) {
                for (int s = 0; s < (indent + 1) * 2; s++) fputc(' ', stdout);
                print_json(v->array_items[i], indent + 1);
                if (i < v->array_count - 1) fputc(',', stdout);
                fputc('\n', stdout);
            }
            for (int s = 0; s < indent * 2; s++) fputc(' ', stdout);
            fputc(']', stdout);
            break;
        case JSON_OBJECT:
            if (v->obj_count == 0) {
                fputs("{}", stdout);
                break;
            }
            fputs("{\n", stdout);
            for (int i = 0; i < v->obj_count; i++) {
                for (int s = 0; s < (indent + 1) * 2; s++) fputc(' ', stdout);
                print_string_escaped(v->obj_keys[i]);
                fputs(": ", stdout);
                print_json(v->obj_values[i], indent + 1);
                if (i < v->obj_count - 1) fputc(',', stdout);
                fputc('\n', stdout);
            }
            for (int s = 0; s < indent * 2; s++) fputc(' ', stdout);
            fputc('}', stdout);
            break;
    }
}

static void free_json(JSONValue *v) {
    if (!v) return;
    switch (v->type) {
        case JSON_STRING:
            free(v->string);
            break;
        case JSON_ARRAY:
            for (int i = 0; i < v->array_count; i++) free_json(v->array_items[i]);
            free(v->array_items);
            break;
        case JSON_OBJECT:
            for (int i = 0; i < v->obj_count; i++) {
                free(v->obj_keys[i]);
                free_json(v->obj_values[i]);
            }
            free(v->obj_keys);
            free(v->obj_values);
            break;
        default: break;
    }
    free(v);
}

static char *read_file(const char *path) {
    FILE *f = fopen(path, "rb");
    if (!f) {
        fprintf(stderr, "Error: cannot open %s\n", path);
        exit(1);
    }
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = (char *)malloc(sz + 1);
    if (!buf) { fprintf(stderr, "Error: malloc failed\n"); exit(1); }
    size_t rd = fread(buf, 1, sz, f);
    buf[rd] = '\0';
    fclose(f);
    return buf;
}

int main(void) {
    const char *path_a = "<tmp>";
    const char *path_b = "<tmp>";

    char *data_a = read_file(path_a);
    char *data_b = read_file(path_b);

    Parser pa = { data_a, 0, (int)strlen(data_a) };
    Parser pb = { data_b, 0, (int)strlen(data_b) };

    JSONValue *a = parse_value(&pa);
    JSONValue *b = parse_value(&pb);

    JSONValue *merged = merge_values(a, b);

    /* Sort all object keys */
    if (merged->type == JSON_OBJECT) {
        sort_obj_keys(merged);
    } else if (merged->type == JSON_ARRAY) {
        sort_array_objects(merged);
    }

    print_json(merged, 0);
    fputc('\n', stdout);

    free_json(a);
    free_json(b);
    free_json(merged);
    free(data_a);
    free(data_b);

    return 0;
}
