import * as fs from 'fs';
import * as path from 'path';

const rootDir = '<tmp>';

interface FileInfo {
  relativePath: string;
  lines: number;
  chars: number;
}

function getExtension(filename: string): string {
  const lastDot = filename.lastIndexOf('.');
  if (lastDot <= 0) return '';
  return filename.slice(lastDot);
}

function countLines(content: Buffer): number {
  if (content.length === 0) return 0;
  let count = 0;
  for (let i = 0; i < content.length; i++) {
    if (content[i] === 0x0a) count++;
  }
  if (content[content.length - 1] !== 0x0a) count++;
  return count;
}

function walk(dir: string, rootDir: string, results: Map<string, FileInfo[]>): void {
  const entries = fs.readdirSync(dir, { withFileTypes: true });
  for (const entry of entries) {
    if (entry.isSymbolicLink()) {
      continue;
    }
    const fullPath = path.join(dir, entry.name);
    const relativePath = path.relative(rootDir, fullPath).split(path.sep).join('/');

    if (entry.isDirectory()) {
      walk(fullPath, rootDir, results);
    } else if (entry.isFile()) {
      const content = fs.readFileSync(fullPath);
      const lines = countLines(content);
      const chars = content.length;
      const ext = getExtension(entry.name);
      if (!results.has(ext)) {
        results.set(ext, []);
      }
      results.get(ext)!.push({ relativePath, lines, chars });
    }
  }
}

const results = new Map<string, FileInfo[]>();
walk(rootDir, rootDir, results);

const exts = Array.from(results.keys()).sort();

for (const ext of exts) {
  results.get(ext)!.sort((a, b) => a.relativePath.localeCompare(b.relativePath));
}

let output = '=== File Tree Analysis ===\n\n';

let totalFiles = 0;
let totalLines = 0;
let totalChars = 0;

for (const ext of exts) {
  const files = results.get(ext)!;
  let extLines = 0;
  let extChars = 0;

  for (const f of files) {
    extLines += f.lines;
    extChars += f.chars;
  }

  output += `Extension: ${ext}\n`;
  output += `  Files: ${files.length}\n`;
  output += `  Total Lines: ${extLines}\n`;
  output += `  Total Characters: ${extChars}\n`;

  for (const f of files) {
    output += `    ${f.relativePath}: ${f.lines} lines, ${f.chars} chars\n`;
  }

  totalFiles += files.length;
  totalLines += extLines;
  totalChars += extChars;
}

output += `\nTotal: ${totalFiles} files, ${totalLines} lines, ${totalChars} characters\n`;

process.stdout.write(output);

