static char *run_command(const char *cmd) {
    FILE *fp = popen(cmd, "r");
    if (!fp) return NULL;

    size_t cap = 4096;
    size_t total = 0;
    char *buf = (char *)malloc(cap);
    if (!buf) {
        pclose(fp);
        return NULL;
    }

    while (fgets(buf + total, (int)(cap - total), fp) != NULL) {
        total += strlen(buf + total);
        if (total >= cap - 1) {
            cap *= 2;
            char *tmp = (char *)realloc(buf, cap);
            if (!tmp) {
                free(buf);
                pclose(fp);
                return NULL;
            }
            buf = tmp;
        }
    }

    pclose(fp);

    while (total > 0 && (buf[total - 1] == '\n' || buf[total - 1] == '\r' ||
                         buf[total - 1] == ' '  || buf[total - 1] == '\t')) {
        total--;
    }
    buf[total] = '\0';

    return buf;
}

