use std::collections::BTreeMap;
use std::fs;
use std::io::Read;
use std::path::{Path, PathBuf};

fn main() {
    let root = PathBuf::from(
        "<tmp>",
    );

    let mut files: Vec<(String, u64, u64)> = Vec::new();

    if root.is_dir() {
        walk(&root, &root, &mut files);
    }

    let mut groups: BTreeMap<String, Vec<(String, u64, u64)>> = BTreeMap::new();

    for (path, lines, chars) in &files {
        let ext = get_extension(path);
        groups.entry(ext).or_default().push((path.clone(), *lines, *chars));
    }

    for v in groups.values_mut() {
        v.sort_by(|a, b| a.0.cmp(&b.0));
    }

    println!("=== File Tree Analysis ===");
    println!();

    let mut total_files: u64 = 0;
    let mut total_lines: u64 = 0;
    let mut total_chars: u64 = 0;

    for (ext, file_list) in &groups {
        let n_files = file_list.len() as u64;
        let n_lines: u64 = file_list.iter().map(|f| f.1).sum();
        let n_chars: u64 = file_list.iter().map(|f| f.2).sum();

        println!("Extension: {}", ext);
        println!("  Files: {}", n_files);
        println!("  Total Lines: {}", n_lines);
        println!("  Total Characters: {}", n_chars);

        for (path, lines, chars) in file_list {
            println!("    {}: {} lines, {} chars", path, lines, chars);
        }

        total_files += n_files;
        total_lines += n_lines;
        total_chars += n_chars;
    }

    println!();
    println!(
        "Total: {} files, {} lines, {} characters",
        total_files, total_lines, total_chars
    );
}

fn walk(root: &Path, current: &Path, files: &mut Vec<(String, u64, u64)>) {
    let entries = match fs::read_dir(current) {
        Ok(e) => e,
        Err(_) => return,
    };

    for entry in entries.flatten() {
        let path = entry.path();

        if path.is_symlink() {
            continue;
        }

        if path.is_dir() {
            walk(root, &path, files);
        } else if path.is_file() {
            let rel = match path.strip_prefix(root) {
                Ok(r) => r,
                Err(_) => continue,
            };
            let rel_str = rel.to_string_lossy().replace('\\', "/");
            let (lines, chars) = read_file_info(&path);
            files.push((rel_str, lines, chars));
        }
    }
}

fn read_file_info(path: &Path) -> (u64, u64) {
    let mut contents: Vec<u8> = Vec::new();
    match fs::File::open(path) {
        Ok(mut f) => {
            if f.read_to_end(&mut contents).is_err() {
                return (0, 0);
            }
        }
        Err(_) => return (0, 0),
    }

    let chars = contents.len() as u64;

    let lines = if contents.is_empty() {
        0
    } else {
        let mut count = contents.iter().filter(|&&b| b == b'\n').count() as u64;
        if *contents.last().unwrap() != b'\n' {
            count += 1;
        }
        count
    };

    (lines, chars)
}

fn get_extension(path: &str) -> String {
    let filename = path.rsplit('/').next().unwrap_or(path);

    if let Some(dot_pos) = filename.rfind('.') {
        if dot_pos > 0 {
            return filename[dot_pos..].to_string();
        }
    }

    String::new()
}

