let B: [[Int]] = [[9,8,7],[6,5,4],[3,2,1]]

let n = A.count
var C = [[Int]](repeating: [Int](repeating: 0, count: n), count: n)
for i in 0..<n {
    for j in 0..<n {
        for k in 0..<n {
            C[i][j] += A[i][k] * B[k][j]
        }
    }
}

