        - C[0][1] * (C[1][0] * C[2][2] - C[1][2] * C[2][0])
        + C[0][2] * (C[1][0] * C[2][1] - C[1][1] * C[2][0])

func printMatrix(_ m: [[Int]]) {
    for row in m {
        let formatted = row.map { String(format: "%4d", $0) }.joined(separator: " ")
        print("  " + formatted)
    }
}

