fn http_get(host: &str, port: u16, path: &str) -> String {
    let addr = format!("{}:{}", host, port);
    let mut stream = TcpStream::connect(&addr).unwrap();
    let request = format!(
        "GET {} HTTP/1.1\r\nHost: {}\r\nConnection: close\r\n\r\n",
        path, host
    );
    stream.write_all(request.as_bytes()).unwrap();

    let mut response = Vec::new();
    stream.read_to_end(&mut response).unwrap();
    let response_str = String::from_utf8(response).unwrap();

    let header_end = response_str.find("\r\n\r\n").unwrap();
    let headers = &response_str[..header_end];
    let body = &response_str[header_end + 4..];

    if headers.to_lowercase().contains("transfer-encoding: chunked") {
        decode_chunked(body)
    } else {
        body.to_string()
    }
}

fn decode_chunked(data: &str) -> String {
    let mut result = String::new();
    let mut remaining = data;
    while !remaining.is_empty() {
        let newline_pos = remaining.find('\n').unwrap_or(remaining.len());
        let size_str = remaining[..newline_pos].trim().trim_end_matches('\r');
        let size = usize::from_str_radix(size_str, 16).unwrap_or(0);
        if size == 0 {
            break;
        }
        let start = newline_pos + 1;
        let end = start + size;
        result.push_str(&remaining[start..end]);
        remaining = &remaining[end + 2..];
    }
    result
}

fn extract_string_field(obj: &str, field: &str) -> String {
    let key = format!("\"{}\"", field);
    let key_pos = obj.find(&key).unwrap();
    let after_key = &obj[key_pos + key.len()..];
    let colon_pos = after_key.find(':').unwrap();
    let after_colon = &after_colon[colon_pos + 1..];
    let quote_start = after_colon.find('"').unwrap();
    let after_quote = &after_colon[quote_start + 1..];
    let mut result = String::new();
    let mut chars = after_quote.chars();
    while let Some(c) = chars.next() {
        if c == '\\' {
            match chars.next() {
                Some('"') => result.push('"'),
                Some('\\') => result.push('\\'),
                Some('n') => result.push('\n'),
                Some('t') => result.push('\t'),
                Some(other) => {
                    result.push('\\');
                    result.push(other);
                }
                None => result.push('\\'),
            }
        } else if c == '"' {
            break;
        } else {
            result.push(c);
        }
    }
    result
}

fn extract_number_field(obj: &str, field: &str) -> f64 {
    let key = format!("\"{}\"", field);
    let key_pos = obj.find(&key).unwrap();
    let after_key = &obj[key_pos + key.len()..];
    let colon_pos = after_key.find(':').unwrap();
    let after_colon = &after_colon[colon_pos + 1..];
    let trimmed = after_colon.trim_start();
    let end = trimmed
        .find(|c: char| c == ',' || c == '}' || c == ' ' || c == '\n' || c == '\r')
        .unwrap_or(trimmed.len());
    trimmed[..end].parse::<f64>().unwrap()
}

fn parse_products(json: &str) -> Vec<(String, f64)> {
    let start = json.find('[').unwrap();
    let end = json.rfind(']').unwrap();
    let inner = &json[start + 1..end];

    let mut results = Vec::new();
    let mut i = 0;
    while i < inner.len() {
        if inner.as_bytes()[i] == b'{' {
            let mut depth = 0;
            let mut j = i;
            while j < inner.len() {
                match inner.as_bytes()[j] {
                    b'{' => depth += 1,
                    b'}' => depth -= 1,
                    _ => {}
                }
                if depth == 0 {
                    break;
                }
                j += 1;
            }
            let obj = &inner[i..=j];
            let name = extract_string_field(obj, "name");
            let price = extract_number_field(obj, "price");
            results.push((name, price));
            i = j + 1;
        } else {
            i += 1;
        }
    }
    results
}

fn main() {
    let body = http_get("127.0.0.1", 18923, "/api/products");
    let products = parse_products(&body);

    let mut filtered: Vec<(String, f64)> = products
        .into_iter()
        .filter(|(_, price)| *price > 50.00)
        .collect();

    filtered.sort_by(|a, b| a.0.cmp(&b.0));

    let total: f64 = filtered.iter().map(|(_, p)| *p).sum();

    println!("=== Filtered Products (price > $50.00) ===");
    println!();
    for (name, price) in &filtered {
        println!("{}: ${:.2}", name, price);
    }
    println!();
    println!("Count: {}", filtered.len());
    println!("Total: ${:.2}", total);
}

