static void add_file(const char *relpath, long lines, long chars) {
    if (file_count >= file_cap) {
        file_cap = file_cap ? file_cap * 2 : 128;
        files = (FileEntry *)realloc(files, (size_t)file_cap * sizeof(FileEntry));
        if (!files) { perror("realloc"); exit(1); }
    }
    files[file_count].relpath = strdup(relpath);
    if (!files[file_count].relpath) { perror("strdup"); exit(1); }

    const char *fname = strrchr(relpath, '/');
    fname = fname ? fname + 1 : relpath;
    const char *dot = strrchr(fname, '.');

    if (dot && dot != fname) {
        files[file_count].ext = strdup(dot);
    } else {
        files[file_count].ext = strdup("");
    }
    if (!files[file_count].ext) { perror("strdup"); exit(1); }

    files[file_count].lines = lines;
    files[file_count].chars = chars;
    file_count++;
}

static void count_file(const char *path, long *lines, long *chars) {
    FILE *f = fopen(path, "rb");
    if (!f) { *lines = 0; *chars = 0; return; }

    long c = 0, nl = 0;
    int ch;
    int last_was_newline = 0;
    int has_content = 0;

    while ((ch = fgetc(f)) != EOF) {
        c++;
        has_content = 1;
        if (ch == '\n') {
            nl++;
            last_was_newline = 1;
        } else {
            last_was_newline = 0;
        }
    }

    *chars = c;
    if (has_content && !last_was_newline) {
        *lines = nl + 1;
    } else {
        *lines = nl;
    }

    fclose(f);
}

static void walk(const char *dirpath, const char *relprefix) {
    DIR *d = opendir(dirpath);
    if (!d) return;

    struct dirent *ent;
    while ((ent = readdir(d)) != NULL) {
        if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0)
            continue;

        char fullpath[8192];
        snprintf(fullpath, sizeof(fullpath), "%s/%s", dirpath, ent->d_name);

        struct stat st;
        if (lstat(fullpath, &st) != 0)
            continue;

        if (S_ISLNK(st.st_mode))
            continue;

        char newrel[8192];
        if (relprefix[0] == '\0')
            snprintf(newrel, sizeof(newrel), "%s", ent->d_name);
        else
            snprintf(newrel, sizeof(newrel), "%s/%s", relprefix, ent->d_name);

        if (S_ISDIR(st.st_mode)) {
            walk(fullpath, newrel);
        } else if (S_ISREG(st.st_mode)) {
            long lines, chars;
            count_file(fullpath, &lines, &chars);
            add_file(newrel, lines, chars);
        }
    }

    closedir(d);
}

