        for (int k = i; k < j; k++) {
            printf("    %s: %ld lines, %ld chars\n", sorted[k]->relpath, sorted[k]->lines, sorted[k]->chars);
        }

        i = j;
    }

    long total_files = (long)file_count;
    long total_lines = 0, total_chars = 0;
