}

struct Parser {
    chars: Vec<char>,
    pos: usize,
}

impl Parser {
    fn new(s: &str) -> Self {
        Parser { chars: s.chars().collect(), pos: 0 }
    }

    fn peek(&self) -> Option<char> {
        self.chars.get(self.pos).copied()
    }

    fn next(&mut self) -> Option<char> {
        let c = self.chars.get(self.pos).copied();
        if c.is_some() {
            self.pos += 1;
        }
        c
    }

    fn skip_whitespace(&mut self) {
        while let Some(c) = self.peek() {
            if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
                self.pos += 1;
            } else {
                break;
            }
        }
    }

    fn expect(&mut self, c: char) {
        self.skip_whitespace();
        assert_eq!(self.next(), Some(c), "Expected '{}'", c);
    }

    fn parse_value(&mut self) -> Json {
        self.skip_whitespace();
        match self.peek() {
            Some('{') => self.parse_object(),
            Some('[') => self.parse_array(),
            Some('"') => Json::Str(self.parse_string()),
            Some('t') => {
                self.parse_literal("true");
                Json::Bool(true)
            }
            Some('f') => {
                self.parse_literal("false");
                Json::Bool(false)
            }
            Some('n') => {
                self.parse_literal("null");
                Json::Null
            }
            _ => self.parse_number(),
        }
    }

    fn parse_literal(&mut self, lit: &str) {
        for c in lit.chars() {
            assert_eq!(self.next(), Some(c));
        }
    }

    fn parse_string(&mut self) -> String {
        self.expect('"');
        let mut s = String::new();
        loop {
            match self.next() {
                Some('"') => break,
                Some('\\') => match self.next() {
                    Some('"') => s.push('"'),
                    Some('\\') => s.push('\\'),
                    Some('/') => s.push('/'),
                    Some('n') => s.push('\n'),
                    Some('t') => s.push('\t'),
                    Some('r') => s.push('\r'),
                    Some('b') => s.push('\u{0008}'),
                    Some('f') => s.push('\u{000C}'),
                    Some('u') => {
                        let mut code: u32 = 0;
                        for _ in 0..4 {
                            let c = self.next().unwrap();
                            code = code * 16 + c.to_digit(16).unwrap();
                        }
                        s.push(char::from_u32(code).unwrap());
                    }
                    _ => panic!("Invalid escape"),
                },
                Some(c) => s.push(c),
                None => panic!("Unterminated string"),
            }
        }
        s
    }

    fn parse_number(&mut self) -> Json {
        let mut s = String::new();
        if self.peek() == Some('-') {
            s.push('-');
            self.pos += 1;
        }
        while let Some(c) = self.peek() {
            if c.is_ascii_digit() || c == '.' || c == 'e' || c == 'E' || c == '+' || c == '-' {
                s.push(c);
                self.pos += 1;
            } else {
                break;
            }
        }
        Json::Number(s.parse().unwrap())
    }

    fn parse_array(&mut self) -> Json {
        self.expect('[');
        let mut arr = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some(']') {
            self.next();
            return Json::Array(arr);
        }
        loop {
            arr.push(self.parse_value());
            self.skip_whitespace();
            match self.next() {
                Some(',') => continue,
                Some(']') => break,
                _ => panic!("Expected ',' or ']'"),
            }
        }
        Json::Array(arr)
    }

    fn parse_object(&mut self) -> Json {
        self.expect('{');
        let mut obj = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some('}') {
            self.next();
            return Json::Object(obj);
        }
        loop {
            self.skip_whitespace();
            let key = self.parse_string();
            self.expect(':');
            let val = self.parse_value();
            obj.push((key, val));
            self.skip_whitespace();
            match self.next() {
                Some(',') => continue,
                Some('}') => break,
                _ => panic!("Expected ',' or '}'"),
            }
        }
        Json::Object(obj)
    }
}

#[derive(PartialEq)]
struct HeapItem {
    dist: f64,
    node: String,
}

impl PartialOrd for HeapItem {
    fn partial_cmp(&self, other: &Self) -> Option<std::cmp::Ordering> {
        self.dist.partial_cmp(&other.dist)
    }
}

impl Ord for HeapItem {
    fn cmp(&self, other: &Self) -> std::cmp::Ordering {
        self.dist.partial_cmp(&other.dist).unwrap_or(std::cmp::Ordering::Equal)
    }
}

fn main() {
    let path = "<tmp>";
    let content = fs::read_to_string(path).unwrap();

    let mut parser = Parser::new(&content);
    let json = parser.parse_value();

    let mut nodes: Vec<String> = Vec::new();
    let mut edges: Vec<(String, String, f64)> = Vec::new();

    if let Json::Object(pairs) = &json {
        for (key, val) in pairs {
            if key == "nodes" {
                if let Json::Array(arr) = val {
                    for item in arr {
                        if let Json::Str(s) = item {
                            nodes.push(s.clone());
                        }
                    }
                }
            } else if key == "edges" {
                if let Json::Array(arr) = val {
                    for item in arr {
                        if let Json::Object(pairs) = item {
                            let mut from = String::new();
                            let mut to = String::new();
                            let mut weight = 0.0f64;
                            for (k, v) in pairs {
                                if k == "from" {
                                    if let Json::Str(s) = v {
                                        from = s.clone();
                                    }
                                } else if k == "to" {
                                    if let Json::Str(s) = v {
                                        to = s.clone();
                                    }
                                } else if k == "weight" {
                                    if let Json::Number(n) = v {
                                        weight = *n;
                                    }
                                }
                            }
                            edges.push((from, to, weight));
                        }
                    }
                }
            }
        }
    }

    // Build adjacency list (undirected)
    let mut adj: HashMap<String, Vec<(String, f64)>> = HashMap::new();
    for node in &nodes {
        adj.entry(node.clone()).or_insert_with(Vec::new);
    }
    for (from, to, weight) in &edges {
        adj.entry(from.clone())
            .or_insert_with(Vec::new)
            .push((to.clone(), *weight));
        adj.entry(to.clone())
            .or_insert_with(Vec::new)
            .push((from.clone(), *weight));
    }

    // Dijkstra's algorithm
    let source = "A".to_string();
    let mut dist: HashMap<String, f64> = HashMap::new();
    for node in &nodes {
        dist.insert(node.clone(), f64::INFINITY);
    }
    dist.insert(source.clone(), 0.0);

    let mut heap: BinaryHeap<Reverse<HeapItem>> = BinaryHeap::new();
    heap.push(Reverse(HeapItem { dist: 0.0, node: source.clone() }));

    let mut visited: HashMap<String, bool> = HashMap::new();

    while let Some(Reverse(item)) = heap.pop() {
        if visited.get(&item.node).copied().unwrap_or(false) {
            continue;
        }
        visited.insert(item.node.clone(), true);

        if let Some(neighbors) = adj.get(&item.node) {
            for (neighbor, weight) in neighbors {
                let new_dist = item.dist + weight;
                if new_dist < dist.get(neighbor).copied().unwrap_or(f64::INFINITY) {
                    dist.insert(neighbor.clone(), new_dist);
                    heap.push(Reverse(HeapItem { dist: new_dist, node: neighbor.clone() }));
                }
            }
        }
    }

    // Output
    let mut sorted_nodes: Vec<&String> = nodes.iter().collect();
    sorted_nodes.sort();

    println!("=== Shortest Paths from A ===");
    println!();
    for node in &sorted_nodes {
        let d = dist.get(*node).copied().unwrap_or(f64::INFINITY);
        if d == f64::INFINITY {
            println!("A -> {}: unreachable", node);
        } else if d == d.floor() {
            println!("A -> {}: {}", node, d as i64);
        } else {
            println!("A -> {}: {}", node, d);
        }
    }
}

