        p++; /* skip opening quote */
        char *start = p;
        while (*p != '"') p++;
        int len = p - start;
        char *node = malloc(len + 1);
        memcpy(node, start, len);
        node[len] = '\0';
        p++; /* skip closing quote */
        if (num_nodes >= 1024) {
            nodes = realloc(nodes, sizeof(char *) * (num_nodes + 1024));
        }
        nodes[num_nodes++] = node;
    }

    /* Parse edges */
    p = strstr(buf, "\"edges\"");
    if (!p) return 1;
    p = strchr(p, '[');
    if (!p) return 1;
    p++;

    Edge **adj = calloc(num_nodes, sizeof(Edge *));

    while (1) {
        while (*p && *p != '{' && *p != ']') p++;
        if (*p == ']' || *p == '\0') break;
        p++; /* skip { */

        int from_idx = -1, to_idx = -1;
        long weight = 0;

        while (*p && *p != '}') {
            while (*p == ' ' || *p == '\t' || *p == '\n' || *p == '\r' || *p == ',') p++;
            if (*p == '}' || *p == '\0') break;
            if (*p != '"') { p++; continue; }
            p++;
            char *key_start = p;
            while (*p != '"') p++;
            int key_len = p - key_start;
            char key[64] = {0};
            if (key_len < 64) memcpy(key, key_start, key_len);
            p++;

            while (*p == ' ' || *p == '\t' || *p == '\n' || *p == '\r') p++;
            if (*p == ':') p++;
            while (*p == ' ' || *p == '\t' || *p == '\n' || *p == '\r') p++;

            if (strcmp(key, "from") == 0) {
                if (*p == '"') {
                    p++;
                    char *s = p;
                    while (*p != '"') p++;
                    int slen = p - s;
                    for (int i = 0; i < num_nodes; i++) {
                        if ((int)strlen(nodes[i]) == slen && strncmp(nodes[i], s, slen) == 0) {
                            from_idx = i;
                            break;
                        }
                    }
                    p++;
                }
            } else if (strcmp(key, "to") == 0) {
                if (*p == '"') {
                    p++;
                    char *s = p;
                    while (*p != '"') p++;
                    int slen = p - s;
                    for (int i = 0; i < num_nodes; i++) {
                        if ((int)strlen(nodes[i]) == slen && strncmp(nodes[i], s, slen) == 0) {
                            to_idx = i;
                            break;
                        }
                    }
                    p++;
                }
            } else if (strcmp(key, "weight") == 0) {
                weight = strtol(p, &p, 10);
            }
        }
        if (*p == '}') p++;

        if (from_idx >= 0 && to_idx >= 0) {
            Edge *e1 = malloc(sizeof(Edge));
            e1->to = to_idx;
            e1->weight = weight;
            e1->next = adj[from_idx];
            adj[from_idx] = e1;

            Edge *e2 = malloc(sizeof(Edge));
            e2->to = from_idx;
            e2->weight = weight;
            e2->next = adj[to_idx];
            adj[to_idx] = e2;
        }
    }

    /* Find start node "A" */
    int start = -1;
    for (int i = 0; i < num_nodes; i++) {
        if (strcmp(nodes[i], "A") == 0) { start = i; break; }
    }
    if (start < 0) return 1;

    /* Dijkstra's algorithm */
    long INF = (long)1e18;
    long *dist = malloc(sizeof(long) * num_nodes);
    int *visited = calloc(num_nodes, sizeof(int));
    for (int i = 0; i < num_nodes; i++) dist[i] = INF;
    dist[start] = 0;

    for (int iter = 0; iter < num_nodes; iter++) {
        int u = -1;
        long min_d = INF;
        for (int i = 0; i < num_nodes; i++) {
            if (!visited[i] && dist[i] < min_d) {
                min_d = dist[i];
                u = i;
            }
        }
        if (u < 0) break;
        visited[u] = 1;

        for (Edge *e = adj[u]; e; e = e->next) {
            int v = e->to;
            if (!visited[v] && dist[u] + e->weight < dist[v]) {
                dist[v] = dist[u] + e->weight;
            }
        }
    }

    /* Sort node indices alphabetically */
    int *order = malloc(sizeof(int) * num_nodes);
    for (int i = 0; i < num_nodes; i++) order[i] = i;
    for (int i = 0; i < num_nodes - 1; i++) {
        for (int j = i + 1; j < num_nodes; j++) {
            if (strcmp(nodes[order[i]], nodes[order[j]]) > 0) {
                int t = order[i];
                order[i] = order[j];
                order[j] = t;
            }
        }
    }

    /* Output */
    printf("=== Shortest Paths from A ===\n\n");
    for (int i = 0; i < num_nodes; i++) {
        int idx = order[i];
        printf("A -> %s: %ld\n", nodes[idx], dist[idx]);
    }

    return 0;
}
