func countLines(_ data: Data) -> Int {
    if let content = String(data: data, encoding: .utf8) {
        if content.isEmpty { return 0 }
        let newlineCount = content.filter { $0 == "\n" }.count
        if content.hasSuffix("\n") {
            return newlineCount
        } else {
            return newlineCount + 1
        }
    } else {
        let newlineCount = data.filter { $0 == 10 }.count
        if data.isEmpty { return 0 }
        if data[data.count - 1] == 10 {
            return newlineCount
        } else {
            return newlineCount + 1
        }
    }
}

func walk(_ url: URL) {
    var isDir: ObjCBool = false
    guard fm.fileExists(atPath: url.path, isDirectory: &isDir) else { return }

    if isDir.boolValue {
        let resolved = url.resolvingSymlinksInPath()
        if visitedDirs.contains(resolved) { return }
        visitedDirs.insert(resolved)

        guard let contents = try? fm.contentsOfDirectory(
            at: url,
            includingPropertiesForKeys: [.isSymbolicLinkKey],
            options: []
        ) else { return }

        for item in contents {
            let values = try? item.resourceValues(forKeys: [.isSymbolicLinkKey])
            if values?.isSymbolicLink == true { continue }
            walk(item)
        }
