        let chars = data.count
        let lines = countLines(data)

        let relativePath = String(url.path.dropFirst(rootDir.count + 1))
        let ext = url.pathExtension
        let extKey = ext.isEmpty ? "(none)" : "." + ext

        if extFiles[extKey] == nil {
