#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

#define MAX_LINE 8192
#define MAX_NAME 256

typedef struct {
    char name[MAX_NAME];
    char dept[MAX_NAME];
    double salary;
} Employee;

typedef struct {
    char name[MAX_NAME];
    double total;
    int count;
} Dept;

static void add_commas(const char *digits, char *out) {
    int len = (int)strlen(digits);
    int pos = 0;
    int count = 0;
    for (int i = len - 1; i >= 0; i--) {
        if (count > 0 && count % 3 == 0) {
            out[pos++] = ',';
        }
        out[pos++] = digits[i];
        count++;
    }
    out[pos] = '\0';
    int s = 0, e = pos - 1;
    while (s < e) {
        char t = out[s]; out[s] = out[e]; out[e] = t;
        s++; e--;
    }
}

static void format_money_int(double val, char *buf, size_t bufsize) {
    long v = (long)(val + 0.5);
    if (v < 0) v = 0;
    char tmp[32];
    snprintf(tmp, sizeof(tmp), "%ld", v);
    char comma[64];
    add_commas(tmp, comma);
    snprintf(buf, bufsize, "$%s", comma);
}

static void format_money_avg(double val, char *buf, size_t bufsize) {
    char tmp[64];
    snprintf(tmp, sizeof(tmp), "%.2f", val);
    char *dot = strchr(tmp, '.');
    char intpart[32] = {0};
    char decpart[4] = {0};
    if (dot) {
        int il = (int)(dot - tmp);
        memcpy(intpart, tmp, il);
        intpart[il] = '\0';
        strncpy(decpart, dot + 1, 3);
        decpart[2] = '\0';
    } else {
        strncpy(intpart, tmp, 31);
    }
    char comma[64];
    add_commas(intpart, comma);
    snprintf(buf, bufsize, "$%s.%s", comma, decpart);
}

static int dept_compare(const void *a, const void *b) {
    const Dept *da = (const Dept *)a;
    const Dept *db = (const Dept *)b;
    return strcmp(da->name, db->name);
}

static void trim(char *s) {
    size_t len = strlen(s);
    while (len > 0 && (s[len-1] == ' ' || s[len-1] == '\t')) s[--len] = '\0';
    size_t start = 0;
    while (s[start] == ' ' || s[start] == '\t') start++;
    if (start > 0) memmove(s, s + start, len - start + 1);
}

int main(void) {
    const char *filename = "<tmp>";
    FILE *f = fopen(filename, "r");
    if (!f) {
        fprintf(stderr, "Error opening file\n");
        return 1;
    }

    Employee *employees = NULL;
    int n_emp = 0, cap_emp = 0;

    char *line = malloc(MAX_LINE);
    if (!line) return 1;

    /* Skip header */
    if (!fgets(line, MAX_LINE, f)) {
        free(line);
        fclose(f);
        return 1;
    }

    while (fgets(line, MAX_LINE, f)) {
        line[strcspn(line, "\r\n")] = '\0';
        if (line[0] == '\0') continue;

        /* Parse 6 fields */
        char *fields[6];
        int nf = 0;
        char *saveptr = NULL;
        char *tok = strtok_r(line, ",", &saveptr);
        while (tok && nf < 6) {
            fields[nf++] = tok;
            tok = strtok_r(NULL, ",", &saveptr);
        }
        if (nf < 6) continue;

        for (int i = 0; i < nf; i++) trim(fields[i]);

        if (cap_emp < n_emp + 1) {
            cap_emp = cap_emp ? cap_emp * 2 : 128;
            employees = realloc(employees, (size_t)cap_emp * sizeof(Employee));
            if (!employees) { free(line); fclose(f); return 1; }
        }
        strncpy(employees[n_emp].name, fields[1], MAX_NAME - 1);
        employees[n_emp].name[MAX_NAME - 1] = '\0';
        strncpy(employees[n_emp].dept, fields[2], MAX_NAME - 1);
        employees[n_emp].dept[MAX_NAME - 1] = '\0';
        employees[n_emp].salary = atof(fields[3]);
        n_emp++;
    }

    free(line);
    fclose(f);

    /* Build department table */
    Dept *depts = NULL;
    int n_depts = 0, cap_depts = 0;

    for (int i = 0; i < n_emp; i++) {
        int found = -1;
        for (int j = 0; j < n_depts; j++) {
            if (strcmp(depts[j].name, employees[i].dept) == 0) {
                found = j;
                break;
            }
        }
        if (found == -1) {
            if (cap_depts < n_depts + 1) {
                cap_depts = cap_depts ? cap_depts * 2 : 64;
                depts = realloc(depts, (size_t)cap_depts * sizeof(Dept));
                if (!depts) { free(employees); return 1; }
            }
            strncpy(depts[n_depts].name, employees[i].dept, MAX_NAME - 1);
            depts[n_depts].name[MAX_NAME - 1] = '\0';
            depts[n_depts].total = 0.0;
            depts[n_depts].count = 0;
            n_depts++;
        }
        depts[found].total += employees[i].salary;
        depts[found].count++;
    }

    /* Sort departments alphabetically */
    qsort(depts, (size_t)n_depts, sizeof(Dept), dept_compare);

    /* Find highest paid */
    int hi_idx = 0;
    for (int i = 1; i < n_emp; i++) {
        if (employees[i].salary > employees[hi_idx].salary) {
            hi_idx = i;
        }
    }

    /* Total budget */
    double total_budget = 0.0;
    for (int i = 0; i < n_emp; i++) {
        total_budget += employees[i].salary;
    }

    /* Output */
    printf("=== Salary Report ===\n");
    printf("\n");
    printf("Average Salary by Department:\n");
    for (int i = 0; i < n_depts; i++) {
        double avg = depts[i].total / (double)depts[i].count;
        char buf[128];
        format_money_avg(avg, buf, sizeof(buf));
        printf("  %s: %s\n", depts[i].name, buf);
    }
    printf("\n");
    {
        char buf[128];
        format_money_int(employees[hi_idx].salary, buf, sizeof(buf));
        printf("Highest Paid: %s (%s)\n", employees[hi_idx].name, buf);
    }
    printf("\n");
    printf("Departments with >2 employees:\n");
    for (int i = 0; i < n_depts; i++) {
        if (depts[i].count > 2) {
            printf("  %s (%d employees)\n", depts[i].name, depts[i].count);
        }
    }
    printf("\n");
    {
        char buf[128];
        format_money_int(total_budget, buf, sizeof(buf));
        printf("Total Budget: %s\n", buf);
    }

    free(employees);
    free(depts);
    return 0;
}

